import pandas as pd
import numpy as np

train = pd.read_csv('b3_te_zt900_train.csv')
pool = pd.read_csv('b3_te_zt900_pool.csv')

# Correlation with target
corr = train.corr()['target'].sort_values(ascending=False)
print("Correlations with target:")
print(corr)

print("\n\n===== Mean target when element present vs absent =====")
feats = [c for c in train.columns if c != 'target']
for f in feats:
    present = train[train[f] > 0]['target']
    absent = train[train[f] == 0]['target']
    print(f"{f:4s} present n={len(present):3d} mean={present.mean():.3f} med={present.median():.3f} max={present.max():.3f} | absent n={len(absent):3d} mean={absent.mean():.3f} med={absent.median():.3f}")

print("\n\n===== Material family analysis =====")
# Define families based on dominant elements
def family(row):
    elems = {c: row[c] for c in feats if row[c] > 0.05}
    keys = set(elems.keys())
    if 'Pb' in keys and 'Te' in keys:
        return 'PbTe'
    if 'Pb' in keys and 'Se' in keys:
        return 'PbSe'
    if 'Cu' in keys and 'Se' in keys:
        return 'CuSe'
    if 'Sn' in keys and 'Se' in keys:
        return 'SnSe'
    if 'O' in keys:
        return 'oxide'
    if 'Co' in keys and 'Sb' in keys:
        return 'skutterudite'
    if 'Ni' in keys and 'Sn' in keys:
        return 'HH_NiSn'
    if 'Fe' in keys and 'Sb' in keys:
        return 'HH_FeSb'
    if 'Si' in keys:
        return 'silicide'
    if 'Ge' in keys:
        return 'germanide'
    if 'Bi' in keys and 'Te' in keys:
        return 'BiTe'
    if 'Zn' in keys and 'Sb' in keys:
        return 'ZnSb'
    return 'other:' + '+'.join(sorted(keys)[:5])

train['family'] = train.apply(family, axis=1)
print(train.groupby('family')['target'].agg(['count','mean','median','max']).sort_values('mean', ascending=False).to_string())

print("\n\n===== Pool families =====")
pool['family'] = pool.apply(family, axis=1)
print(pool['family'].value_counts())
print("\nPool by family:")
print(pool.groupby('family')['candidate_id'].apply(list).to_string())
